def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    me = [h[0] for h in history]
    opp = [h[1] for h in history]
    last_opp = opp[-1]
    last_me = me[-1]

    opp_c = opp.count('C')
    opp_d = n - opp_c

    # Endgame: against cooperative opponents, defect at the very end.
    if n >= 98:
        if opp_c >= n - 3:
            return 'D'
        return 'C'
    if n >= 95:
        if opp_c >= int(0.85 * n):
            return 'D'
        return last_opp

    # Immediate retaliation with brief forgiveness to recover from noise.
    if last_opp == 'D':
        if last_me == 'C':
            return 'D'
        # We also defected: try to break DD cycles occasionally.
        streak = 0
        for a in reversed(opp):
            if a == 'D':
                streak += 1
            else:
                break
        if streak >= 2 and rng.random() < 0.15:
            return 'C'
        return 'D'

    # Opponent just cooperated.
    if n < 6:
        return 'C'

    # Almost-always defector: mostly defend, rare probes.
    if opp_d >= n - 1 and n >= 8:
        if rng.random() < 0.05:
            return 'C'
        return 'D'

    # Very cooperative opponent: mostly cooperate, slight probing.
    if opp_c >= int(0.9 * n) and n >= 12:
        if rng.random() < 0.06:
            return 'D'
        return 'C'

    # Recent window analysis.
    w = min(15, n)
    recent_c = sum(1 for a in opp[-w:] if a == 'C')
    recent_rate = recent_c / float(w)

    if recent_rate >= 0.75:
        return 'C'
    if recent_rate >= 0.4:
        return last_opp
    # Recent mostly defection: defect with rare probing.
    if rng.random() < 0.07:
        return 'C'
    return 'D'
